type DenialReason =
  | { type: "throughput_sla" }
  | { type: string };

interface EndpointCandidate {
  id: string;
  allowListed: boolean;
  hardDenied: boolean;
  hardDenialReasons?: DenialReason[];
}

interface RoutingRequest {
  remoteOnly: boolean;
}

export function shouldAllowSoleCandidateThroughputFallback(
  request: RoutingRequest,
  allowListedEndpoints: EndpointCandidate[]
): boolean {
  if (!request.remoteOnly) {
    return false;
  }

  if (allowListedEndpoints.length !== 1) {
    return false;
  }

  const [soleCandidate] = allowListedEndpoints;

  if (!soleCandidate.allowListed || !soleCandidate.hardDenied) {
    return false;
  }

  const reasons = soleCandidate.hardDenialReasons ?? [];

  if (reasons.length === 0) {
    return false;
  }

  return reasons.every((reason) => reason.type === "throughput_sla");
}
```

